import React from "react";
import { Audio } from "@remotion/media";
import { interpolate, Sequence, staticFile } from "remotion";
import { AUDIO, HANDOFF, SCENES, VIDEO } from "./theme";
import { PROBLEM_SFX } from "./scenes/Problem";
import { FIX_SFX } from "./scenes/Fix";
import { PAYOFF_SFX } from "./scenes/Payoff";

// Music bed + light SFX. Every cue comes from the scene's own beat constants, so retiming a scene
// moves its sounds with it. Audio files are generated by scripts/make-audio.py (seeded, no samples).

type Cue = { at: number; file: string; volume: number; name: string };

const cues = (): Cue[] => {
  const P = SCENES.problem.from;
  const F = SCENES.fix.from;
  const Y = SCENES.payoff.from;
  const list: Cue[] = [];
  const add = (at: number, file: string, volume: number, name: string) => list.push({ at: Math.round(at), file, volume, name });

  add(SCENES.hook.duration - HANDOFF.matchCut, "whoosh.wav", AUDIO.whoosh * 0.8, "1D whoosh");
  add(P + PROBLEM_SFX.pmMsg, "ping.wav", AUDIO.ping, "PM ping");
  PROBLEM_SFX.clicks.forEach((f, i) => add(P + f, "click.wav", AUDIO.click * 0.8, `copy-paste click ${i + 1}`));
  add(P + PROBLEM_SFX.ping, "ping-alert.wav", AUDIO.ping * 1.15, "CTO ping");
  add(P + PROBLEM_SFX.wipe, "whoosh.wav", AUDIO.whoosh, "2D wipe whoosh");

  add(F + FIX_SFX.generate, "click.wav", AUDIO.click, "Generate click");
  FIX_SFX.lands.forEach((f, i) => add(F + f, "tick.wav", AUDIO.chipTick, `chip ${i + 1}`));
  FIX_SFX.lines.forEach((f, i) => add(F + f, "type.wav", AUDIO.type, `line ${i + 1}`));
  add(F + FIX_SFX.ready, "pop.wav", AUDIO.pop, "Ready badge");
  add(F + FIX_SFX.publish, "click.wav", AUDIO.click, "Publish click");

  add(Y + PAYOFF_SFX.clockGreen, "chime.wav", AUDIO.chime, "4:51 green");
  add(Y + PAYOFF_SFX.pmMsg, "ping.wav", AUDIO.ping * 0.7, "PM reply");
  add(Y + PAYOFF_SFX.reactions, "pop.wav", AUDIO.pop * 0.7, "reactions");
  add(Y + PAYOFF_SFX.logo, "hit.wav", AUDIO.hit, "logo hit");
  add(Y + PAYOFF_SFX.ctaPress, "click.wav", AUDIO.click, "CTA click");
  return list;
};

export const Soundtrack: React.FC = () => {
  if (!AUDIO.enabled) return null;
  return (
    <>
      <Audio
        src={staticFile("audio/bed.wav")}
        volume={(f) =>
          AUDIO.bed *
          interpolate(f, [0, 20, VIDEO.durationInFrames - 30, VIDEO.durationInFrames], [0, 1, 1, 0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          })
        }
      />
      {cues().map((c, i) => (
        <Sequence key={i} from={c.at} durationInFrames={150} name={`sfx · ${c.name}`} layout="none">
          <Audio src={staticFile(`audio/${c.file}`)} volume={c.volume} />
        </Sequence>
      ))}
    </>
  );
};
